<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useClock} from '../../composables/useClock.js'
import {useListState} from '../../composables/useListState.js'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import {columns,ordered,dateText,actionNames} from '../alarms/supportUi.js'
const r=useIrrigation(),router=useRouter(),route=useRoute(),clock=useClock(),state=useListState('audit',{filters:{actorId:'',entityType:'',start:clock.isReference?'2026-06-01':new Date(Date.now()-29*86400000).toISOString().slice(0,10),end:clock.isReference?'2026-07-28':clock.today.value}}),filters=ref({...state.filters})
if(route.query.selected)state.selectedId=route.query.selected
const entityTypes={IrrigationRun:'灌溉运行',RunStep:'轮灌步骤',WaterLedger:'用水账本',Field:'田块',CropSeason:'种植季',Device:'设备',Point:'点位',IrrigationZone:'轮灌分区',PipeNode:'管段',Strategy:'灌溉策略',Plan:'灌溉计划',Alarm:'运行告警',WorkOrder:'维护工单',User:'账号',SystemPolicy:'运行参数',ExportJob:'导出任务'},failure=ref('')
const rows=computed(()=>{const start=Date.parse(state.filters.start+'T00:00:00+08:00'),end=Date.parse(state.filters.end+'T00:00:00+08:00')+86400000;return ordered((r.state.entities.AuditLog??[]).filter(a=>(!state.filters.actorId||a.actorId===state.filters.actorId)&&(!state.filters.entityType||a.entityType===state.filters.entityType)&&Date.parse(a.occurredAt)>=start&&Date.parse(a.occurredAt)<end).sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt)||a.auditId.localeCompare(b.auditId)),state.sort)}),visible=computed(()=>rows.value.slice((state.page-1)*15,state.page*15)),selected=computed(()=>rows.value.find(x=>x.auditId===state.selectedId)),command=computed(()=>(r.state.entities.CommandOutbox??[]).find(c=>c.commandId===selected.value?.detail?.commandId||selected.value?.correlationId&&c.correlationId===selected.value.correlationId)),events=computed(()=>(r.state.entities.CommandEvent??[]).filter(e=>e.commandId===command.value?.commandId).sort((a,b)=>Date.parse(a.occurredAt)-Date.parse(b.occurredAt))),get=(kind,id)=>r.getIndex().byId[kind]?.get(id)
watch(visible,list=>{if(!list.some(a=>a.auditId===state.selectedId))state.selectedId=list[0]?.auditId??null},{immediate:true})
const cols=columns([['number','序号',75],['auditId','审计编号',260],['actorId','操作人',140],['actionId','动作',170],['entityId','对象编号',240],['occurredAt','发生时间',220],['result','结果',125]])
const names={...actionNames,RUN_STEP_FINISH:'结束步骤',RUN_ADVANCE:'切换分区'}
function query(){failure.value='';if(!filters.value.start||!filters.value.end||filters.value.start>filters.value.end){failure.value='请选择有效日期区间，开始日期不能晚于结束日期';return}state.filters={...filters.value};state.page=1}
function objectRoute(type,id){const map={Field:'/fields/',Device:'/devices/',Strategy:'/strategies/',Plan:'/plans/',IrrigationRun:'/runs/'};if(map[type]&&get(type,id))return map[type]+id+(['Strategy','Plan'].includes(type)?'/edit':'');if(type==='WorkOrder'&&get(type,id))return {path:'/maintenance',query:{selected:id}};if(type==='Alarm'&&get(type,id))return {path:'/alarms',query:{selected:id}};if(type==='WaterLedger'&&get(type,id)){const ledger=get(type,id),zone=get('IrrigationZone',ledger.zoneId);return {path:'/water',query:{fieldId:zone?.fieldId}}}if(type==='RunStep'&&get(type,id))return '/runs/'+get(type,id).runId;if(type==='CropSeason'&&get(type,id))return '/fields/'+get(type,id).fieldId;if(type==='Point'&&get(type,id))return '/devices/'+get(type,id).deviceId;if(['IrrigationZone','PipeNode'].includes(type)&&get(type,id))return {path:'/network',query:{selected:id}};if(['User','SystemPolicy'].includes(type)&&get(type,id))return '/settings';if(type==='ExportJob'&&get(type,id))return '/water';return null}
function drill(row){const target=objectRoute(row.entityType,row.entityId);if(target)router.push(target)}
const phases=computed(()=>{const c=command.value;if(!c)return [];const ackSeen=events.value.some(e=>e.phase==='ACKNOWLEDGED'),confirmationSeen=events.value.some(e=>e.phase==='CONFIRMED');const confirmedText=c.intent==='START'?'灌溉已启动，执行中':c.intent==='STOP'?'已确认停止动作':'已收到动作确认';return [{label:'受理',at:c.requestedAt,text:c.requestedAt?'指令已受理，进入处理队列':'待受理记录'},{label:'应答',at:c.ackAt,text:c.ackAt?'已收到应答，等待动作确认':ackSeen?'已收到设备应答，等待完整命令应答':'待反馈'},{label:'动作确认',at:c.confirmedAt,text:c.confirmedAt?confirmedText:confirmationSeen?'已收到设备确认反馈，等待命令级确认':'待反馈'}]})
</script>
<template><div class="page-stack audit-page"><section class="panel audit-list"><form class="filters audit-filters" @submit.prevent="query"><label class="filter-field">操作人<select v-model="filters.actorId"><option value="">全部</option><option v-for="u in r.state.entities.User" :key="u.userId" :value="u.userId">{{u.name}}</option></select></label><label class="filter-field">对象<select v-model="filters.entityType"><option value="">全部</option><option v-for="(label,key) in entityTypes" :key="key" :value="key">{{label}}</option></select></label><label class="filter-field date-filter">区间<span><input v-model="filters.start" type="date" aria-label="开始日期"/>—<input v-model="filters.end" type="date" aria-label="结束日期"/></span></label><button class="btn btn-primary">查询</button></form><p v-if="failure" role="alert" class="error-text">{{failure}}</p><DataTable :columns="cols" :rows="visible" row-key="auditId" :selected-id="state.selectedId" :sort="state.sort" compact @row-click="state.selectedId=$event.auditId" @update:sort="state.sort=$event"><template #cell-number="{index}">{{(state.page-1)*15+index+1}}</template><template #cell-actorId="{value}">{{get('User',value)?.name||value||'—'}}</template><template #cell-actionId="{value}">{{names[value]||value}}</template><template #cell-entityId="{row,value}"><button v-if="objectRoute(row.entityType,value)" class="btn-link audit-object" @click.stop="drill(row)">{{value}}</button><span v-else :title="value?'关联记录不存在或无权查看':''">{{value||'—'}}</span></template><template #cell-occurredAt="{value}">{{dateText(value,true)}}</template><template #cell-result="{value}"><StatusBadge :status="value" :text="{ACCEPTED:'已受理',SUCCESS:'成功',FAILED:'失败',REJECTED:'拒绝'}[value]||value" :tone="value==='ACCEPTED'?'warning':value==='SUCCESS'?'success':'danger'"/></template></DataTable><Pagination v-model="state.page" :total="rows.length"/></section><section class="panel audit-chain"><h2 class="panel-title">审计事件链路</h2><template v-if="selected"><div class="chain-meta"><span>审计编号 <strong>{{selected.auditId}}</strong></span><span>对象编号 <button v-if="objectRoute(selected.entityType,selected.entityId)" class="btn-link" @click="drill(selected)">{{selected.entityId}}</button><strong v-else>{{selected.entityId||'—'}}</strong></span><span>指令编号 <strong>{{command?.commandId||'无关联指令'}}</strong></span><span>关联编号 <strong>{{selected.correlationId||'—'}}</strong></span><span>操作人 <strong>{{get('User',selected.actorId)?.name||selected.actorId}}</strong></span></div><div v-if="command" class="command-phases"><div v-for="(phase,i) in phases" :key="phase.label" class="command-phase" :class="{waiting:!phase.at}"><div class="phase-heading"><span>{{i+1}}</span><strong>{{phase.label}}</strong><b v-if="i<2" class="phase-arrow"/></div><time>{{dateText(phase.at)}}</time><p>{{phase.text}}</p></div></div><div v-else class="audit-fact"><strong>{{names[selected.actionId]||selected.actionId}} · {{dateText(selected.occurredAt)}}</strong><p>版本：{{selected.beforeVersion??'新建'}} → {{selected.afterVersion??'—'}} · {{selected.result==='SUCCESS'?'保存成功':selected.result}}</p><p>{{selected.detail?.note||'此事件无关联指令，依据操作审计记录展示。'}}</p></div></template><p v-else class="empty-state">没有符合条件的审计记录，请调整操作人、对象或日期区间。</p></section></div></template>
<style scoped>.audit-page{gap:16px;padding-top:0}.audit-list{padding:14px 14px 0}.audit-filters{display:grid;grid-template-columns:minmax(252px,1fr) minmax(237px,.95fr) minmax(386px,1.5fr) 118px;align-items:center;gap:0 27px;padding:0 4px 19px;height:auto;min-height:60px}.audit-filters .filter-field{display:flex;flex:none;min-width:0;flex-direction:row;gap:18px;align-items:center;white-space:nowrap}.audit-filters select{width:191px;min-width:0;height:40px}.audit-filters .btn{height:40px;min-width:118px;width:118px}.date-filter>span{display:flex;align-items:center;min-width:0;width:100%;flex:1;border:1px solid #d7e2dc;border-radius:5px;padding:0 6px}.date-filter input{flex:1 1 0;width:0;min-width:0;min-height:38px;border:0;padding:4px 6px}@media(max-width:1420px){.audit-filters{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px 22px;padding-bottom:16px}.audit-filters .filter-field{width:100%}.audit-filters select{width:min(191px,calc(100% - 70px))}.audit-filters .date-filter{grid-column:1}.date-filter>span{flex:1}.audit-filters .btn{grid-column:2;justify-self:start}}@media(max-width:650px){.audit-filters{grid-template-columns:minmax(0,1fr);gap:12px}.audit-filters .date-filter,.audit-filters .btn{grid-column:1}.audit-filters .filter-field{justify-content:space-between}.audit-filters select{flex:1;width:auto}.date-filter>span{width:calc(100% - 60px);flex:none}}.audit-list :deep(td){height:33px;padding-top:2px;padding-bottom:2px;font-size:14px}.audit-list :deep(th){height:38px;font-size:14px}.audit-list :deep(.pagination){height:66px}.audit-object{font-size:14px;color:#20342f}.audit-chain{min-height:225px;padding:15px 18px}.audit-chain .panel-title{font-size:18px;margin-bottom:17px}.chain-meta{display:flex;gap:23px;align-items:center;font-size:14px;white-space:nowrap}.chain-meta>span+span{border-left:1px solid #9eb4a9;padding-left:23px}.chain-meta strong{font-weight:400;margin-left:12px}.chain-meta .btn-link{font-size:14px;color:#20342f;margin-left:10px}.command-phases{display:grid;grid-template-columns:repeat(3,1fr);gap:32px;margin-top:20px}.phase-heading{display:flex;align-items:center;gap:16px;position:relative}.phase-heading>span{width:34px;height:34px;background:#00895b;border-radius:50%;color:white;display:grid;place-items:center;flex-shrink:0}.phase-arrow{height:2px;flex:1;background:#009461;position:relative;margin-left:6px}.phase-arrow:after{content:'';position:absolute;right:0;top:-5px;width:10px;height:10px;border-top:2px solid #009461;border-right:2px solid #009461;transform:rotate(45deg)}.command-phase time{display:block;color:#647d71;font-size:14px;margin-left:50px;margin-top:0}.command-phase p{background:#ecfaf3;padding:10px 15px;margin:9px 0 0 34px;font-size:14px}.command-phase.waiting .phase-heading>span{background:#99a69f}.command-phase.waiting p{background:#f1f4f2}.audit-fact{margin-top:18px;padding:12px 16px;background:#f1f8f4;font-size:14px}.audit-fact p{margin:7px 0 0}
</style>
